"""Independent Subtangle and 2034/A-C solutions."""
import json
from pathlib import Path
GAME=r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int l,n,m;cin>>l>>n>>m;vector<int>a(l);for(int&x:a)cin>>x;vector<vector<pair<int,int>>>occ(n*m+1);vector<int>seen(n*m+1,-1);for(int i=0;i<n;i++){vector<int>row(m);for(int&x:row)cin>>x;for(int j=m-1;j>=0;j--)if(seen[row[j]]!=i){seen[row[j]]=i;occ[row[j]].push_back({i,j+1});}}vector<int>next(n+1),cur(n+1);for(int k=l-1;k>=0;k--){fill(cur.begin(),cur.end(),0);for(auto p:occ[a[k]])if(p.second>=next[p.first+1])cur[p.first]=max(cur[p.first],p.second);for(int i=n-1;i>=0;i--)cur[i]=max(cur[i],cur[i+1]);next.swap(cur);}cout<<(next[0]?"T":"N")<<'\n';}}'''
WHY='For each stage, winning suffix rectangles are described by an array f[r]: the largest column of a winning move in rows >=r. A move at (r,c) is winning iff its value matches and the next player loses in suffix (r+1,c+1), equivalently fNext[r+1]<=c. For each value and row only the rightmost occurrence matters: it dominates every smaller column both in successor losing condition and feasible suffixes. Precompute those rightmost positions. Process stages backward, mark qualifying positions and suffix-max their columns. No moves after the last stage is losing. O(n*m+l*n) time and O(n*m+n+l) space, sufficient for both versions.'
ANSWERS=[('2005/E1',WHY,GAME),('2005/E2',WHY,GAME),
('2034/A','If the common remainder is r, then m-r is a common multiple of a and b. Since m>=min(a,b)>r, this multiple is positive and at least lcm(a,b). The least feasible m is therefore lcm(a,b), with remainder zero. O(log min(a,b)) time, O(1) space.',r'''#include <bits/stdc++.h>
using namespace std;int main(){int t;cin>>t;while(t--){long long a,b;cin>>a>>b;cout<<a/__gcd(a,b)*b<<'\n';}}'''),
('2034/B','Scan left to right counting consecutive zeros. When m zeros are encountered an operation is necessary; start it at the last zero, extending k cells right (or shift left to fit at the end). This hits the earliest uncovered forbidden interval and maximizes coverage to its right, so an exchange argument proves optimality. Skip the now strengthened k cells and reset the zero count. O(n) time, O(1) extra space.',r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n,m,k;string s;cin>>n>>m>>k>>s;int zeros=0,ans=0;for(int i=0;i<n;i++){if(s[i]=='1')zeros=0;else ++zeros;if(zeros==m){++ans;zeros=0;i+=k-1;}}cout<<ans<<'\n';}}'''),
('2034/C','Build a directed possibility graph: fixed cells have their single in-grid outgoing edge; question marks have edges to all in-grid neighbors. Repeatedly remove vertices with outdegree zero, updating reverse neighbors. Removed vertices necessarily escape regardless of assignments. Every surviving vertex has a surviving successor, so assign each surviving question mark to one and keep all survivors trapped in cycles or paths to cycles. This simultaneously attains the upper bound. O(n*m) time and space.',r'''#include <bits/stdc++.h>
using namespace std;int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int t;cin>>t;while(t--){int n,m;cin>>n>>m;vector<string>a(n);for(auto&s:a)cin>>s;int N=n*m;vector<vector<int>>rev(N);vector<int>deg(N);int di[4]={-1,1,0,0},dj[4]={0,0,-1,1};string dirs="UDLR";for(int i=0;i<n;i++)for(int j=0;j<m;j++)for(int k=0;k<4;k++)if(a[i][j]=='?'||a[i][j]==dirs[k]){int r=i+di[k],c=j+dj[k];if(r>=0&&r<n&&c>=0&&c<m){deg[i*m+j]++;rev[r*m+c].push_back(i*m+j);}}queue<int>q;for(int i=0;i<N;i++)if(!deg[i])q.push(i);int ans=N;while(!q.empty()){int u=q.front();q.pop();--ans;for(int v:rev[u])if(--deg[v]==0)q.push(v);}cout<<ans<<'\n';}}''')]
if __name__=='__main__':
    p=Path('backend/data/bench/codeforces700_20261116/assistant_answers_v1/shard_test_000_199.jsonl')
    with p.open('a',encoding='utf-8') as out:
        for ident,explanation,code in ANSWERS:
            out.write(json.dumps({'id':ident,'split':'test','author':'current chat assistant','status':'authored','explanation':explanation,'cpp_code':code,'validation':'not executed'})+'\n')
